import{_ as e,o,c as t,a5 as a}from"./chunks/framework.Cooo9kuv.js";const g=JSON.parse('{"title":"WordPress Markdown 导出插件 — WP Markdown Export","description":"","frontmatter":{"标题":"WordPress Markdown 导出插件 — WP Markdown Export","日期":"2026-07-12T00:00:00.000Z","修改日期":"2026-07-13T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["wordpress主题插件"],"标签":["Front Matter","Hexo","Hugo","Jekyll","markdown","WordPress","内容导出","文章备份","网站迁移","静态站点"]},"headers":[{"level":2,"title":"插件简介","slug":"插件简介","link":"#插件简介","children":[]},{"level":2,"title":"功能特性","slug":"功能特性","link":"#功能特性","children":[{"level":3,"title":"自实现 HTML 转 Markdown 引擎，零依赖","slug":"自实现-html-转-markdown-引擎-零依赖","link":"#自实现-html-转-markdown-引擎-零依赖","children":[]},{"level":3,"title":"YAML Front Matter 元数据头","slug":"yaml-front-matter-元数据头","link":"#yaml-front-matter-元数据头","children":[]},{"level":3,"title":"WordPress 特有内容智能预处理","slug":"wordpress-特有内容智能预处理","link":"#wordpress-特有内容智能预处理","children":[]},{"level":3,"title":"单篇导出与批量导出","slug":"单篇导出与批量导出","link":"#单篇导出与批量导出","children":[]},{"level":3,"title":"文章筛选与批量选择","slug":"文章筛选与批量选择","link":"#文章筛选与批量选择","children":[]},{"level":3,"title":"导出选项灵活配置","slug":"导出选项灵活配置","link":"#导出选项灵活配置","children":[]},{"level":3,"title":"中英文双语界面","slug":"中英文双语界面","link":"#中英文双语界面","children":[]},{"level":3,"title":"导出配置持久化","slug":"导出配置持久化","link":"#导出配置持久化","children":[]}]},{"level":2,"title":"使用说明","slug":"使用说明","link":"#使用说明","children":[{"level":3,"title":"第一步：安装插件","slug":"第一步-安装插件","link":"#第一步-安装插件","children":[]},{"level":3,"title":"第二步：单篇导出（快捷方式）","slug":"第二步-单篇导出-快捷方式","link":"#第二步-单篇导出-快捷方式","children":[]},{"level":3,"title":"第三步：批量导出","slug":"第三步-批量导出","link":"#第三步-批量导出","children":[]},{"level":3,"title":"第四步：验证导出结果","slug":"第四步-验证导出结果","link":"#第四步-验证导出结果","children":[]}]},{"level":2,"title":"注意事项","slug":"注意事项","link":"#注意事项","children":[]},{"level":2,"title":"反馈与支持","slug":"反馈与支持","link":"#反馈与支持","children":[]},{"level":2,"title":"更新日志","slug":"更新日志","link":"#更新日志","children":[{"level":3,"title":"v1.0.0（2026-07-12）","slug":"v1-0-0-2026-07-12","link":"#v1-0-0-2026-07-12","children":[]}]}],"relativePath":"md/wordpress主题插件/WordPress Markdown 导出插件 — WP Markdown Export.md","filePath":"md/wordpress主题插件/WordPress Markdown 导出插件 — WP Markdown Export.md"}'),n={name:"md/wordpress主题插件/WordPress Markdown 导出插件 — WP Markdown Export.md"};function l(d,r,s,i,c,h){return o(),t("div",null,[...r[0]||(r[0]=[a('<h1 id="wordpress-markdown-导出插件-—-wp-markdown-export" tabindex="-1">WordPress Markdown 导出插件 — WP Markdown Export <a class="header-anchor" href="#wordpress-markdown-导出插件-—-wp-markdown-export" aria-label="Permalink to &quot;WordPress Markdown 导出插件 — WP Markdown Export&quot;">​</a></h1><blockquote><p>将 WordPress 文章和页面导出为 Markdown 格式文件，支持 YAML Front Matter 元数据头。零外部依赖，开箱即用。单篇导出和批量 ZIP 导出均可，兼容 Hugo、Jekyll、Hexo 等主流静态站点生成器。</p></blockquote><p><strong>版本</strong>：v1.0.0<br><strong>适配</strong>：WordPress 5.8+<br><strong>PHP</strong>：≥ 7.2<br><strong>作者</strong>：softbangong<br><strong>授权</strong>：不限制网站数量，下载安装后永久免费使用</p><h2 id="插件简介" tabindex="-1">插件简介 <a class="header-anchor" href="#插件简介" aria-label="Permalink to &quot;插件简介&quot;">​</a></h2><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/image-31.png" alt=""></p><p>本插件用于将 WordPress 中的文章和页面内容导出为标准的 Markdown 文件。导出的 Markdown 文件可直接导入 Hugo、Jekyll、Hexo 等静态站点生成器使用，也可用于网站内容迁移、本地备份存档或跨平台内容分发。</p><p>插件采用自实现的 DOMDocument 驱动的 HTML 转 Markdown 引擎，无需任何第三方依赖库，安装即用。导出时自动处理 WordPress 特有的内容格式，包括 Gutenberg 代码块、图文混排（figure/caption）、嵌入内容（oEmbed）和短代码等，确保转换结果干净、规范。</p><p>管理界面提供文章筛选、批量选择、导出选项配置和语言切换功能，所有设置可持久化保存。同时，每篇文章和页面的行操作菜单中均提供「导出 Markdown」快捷入口，方便单篇快速导出。</p><h2 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to &quot;功能特性&quot;">​</a></h2><h3 id="自实现-html-转-markdown-引擎-零依赖" tabindex="-1">自实现 HTML 转 Markdown 引擎，零依赖 <a class="header-anchor" href="#自实现-html-转-markdown-引擎-零依赖" aria-label="Permalink to &quot;自实现 HTML 转 Markdown 引擎，零依赖&quot;">​</a></h3><p>插件内置完整的 HTML 转 Markdown 转换器，基于 PHP DOMDocument 递归解析 HTML 节点，无需 Parsedown、League/HTMLToMarkdown 等第三方库：</p><p>— 标题（H1-H6）转换为对应级别的 <code>#</code> 语法；<br> — 粗体、斜体、删除线等行内格式完整保留；<br> — 行内代码和围栏代码块正确转换，代码块自动识别语言标注（如 <code>php</code>、<code>javascript</code>）；<br> — 有序列表和无序列表支持嵌套缩进；<br> — HTML 表格转换为 GFM 格式的 Markdown 表格；<br> — 引用块转换为 <code>&gt;</code> 前缀格式；<br> — 图片和链接的 alt、title 属性完整保留。</p><h3 id="yaml-front-matter-元数据头" tabindex="-1">YAML Front Matter 元数据头 <a class="header-anchor" href="#yaml-front-matter-元数据头" aria-label="Permalink to &quot;YAML Front Matter 元数据头&quot;">​</a></h3><p>导出时可在文件顶部自动生成 YAML 格式的 Front Matter 元数据头，字段可精细控制：</p><p>— 标题（title）：文章标题，自动转义 YAML 特殊字符；<br> — 日期（date）：文章发布日期，格式为 YYYY-MM-DD；<br> — 修改日期（modified）：最后修改日期；<br> — 作者（author）：文章作者显示名称；<br> — 别名（slug）：文章 URL 别名；<br> — 状态（status）：文章发布状态（publish/draft/pending/private）；<br> — 分类（categories）：文章所属分类列表，YAML 数组格式；<br> — 标签（tags）：文章标签列表，YAML 数组格式；<br> — 特色图片（featured_image）：文章特色图片完整 URL；<br> — 摘要（excerpt）：文章摘要内容。</p><p>以上每个字段均可独立开启或关闭。开启 Front Matter 总开关后，默认可视化展开所有字段选项。Front Matter 的字段名（key）跟随插件界面语言设置，中文模式下显示中文键名，英文模式下显示英文键名。</p><h3 id="wordpress-特有内容智能预处理" tabindex="-1">WordPress 特有内容智能预处理 <a class="header-anchor" href="#wordpress-特有内容智能预处理" aria-label="Permalink to &quot;WordPress 特有内容智能预处理&quot;">​</a></h3><p>导出引擎在转换前会对 WordPress 内容进行专项预处理，确保转换结果准确规范：</p><p>— <strong>图文混排（figure）</strong>：自动提取 <code>&lt;figure&gt;</code> 中的图片和 <code>&lt;figcaption&gt;</code> 说明文字，生成 <code>![alt](url)</code> 格式；<br> — <strong>Caption 短代码</strong>：识别 <code>...</code> 旧版短代码，提取图片和标题文字；<br> — <strong>Gutenberg 代码块</strong>：处理 <code>wp-block-code</code> 样式块，自动识别并保留语言标注；<br> — <strong>嵌入内容（oEmbed）</strong>：将 YouTube、Twitter 等嵌入块转为 HTML 注释形式（<code>&lt;!-- embed: url --&gt;</code>），保留原始链接；<br> — <strong>短代码保留</strong>：可选保留或移除文章中的 WordPress 短代码，保留模式下原样输出 <code>[gallery]</code>、<code>[contact-form-7]</code> 等标记；<br> — <strong>more 标签</strong>：<code>&lt;!--more--&gt;</code> 标签在导出内容中原样保留。</p><h3 id="单篇导出与批量导出" tabindex="-1">单篇导出与批量导出 <a class="header-anchor" href="#单篇导出与批量导出" aria-label="Permalink to &quot;单篇导出与批量导出&quot;">​</a></h3><p>— <strong>单篇导出</strong>：在文章列表页面，每篇文章和页面的行操作菜单中增加「导出 Markdown」链接，点击后直接下载该篇的 <code>.md</code> 文件；<br> — <strong>批量导出</strong>：进入「工具 → Markdown 导出」管理页面，可多选文章后一键导出为 ZIP 压缩包。ZIP 包内按日期组织文件夹（如 <code>wp-markdown-export-2026-07-12/</code>），每篇文章以标题命名 <code>.md</code> 文件。</p><h3 id="文章筛选与批量选择" tabindex="-1">文章筛选与批量选择 <a class="header-anchor" href="#文章筛选与批量选择" aria-label="Permalink to &quot;文章筛选与批量选择&quot;">​</a></h3><p>管理界面提供便捷的筛选和选择工具：</p><p>— 按分类筛选：下拉选择任意分类，仅显示该分类下的文章；<br> — 按状态筛选：可选已发布、草稿、待审核、私密等状态；<br> — 日期范围筛选：设定起止日期，精确查找时间段内的文章；<br> — 全选/取消全选：表头复选框一键勾选当前页全部文章；<br> — 分页浏览：每页显示 20 篇文章，支持翻页导航。</p><h3 id="导出选项灵活配置" tabindex="-1">导出选项灵活配置 <a class="header-anchor" href="#导出选项灵活配置" aria-label="Permalink to &quot;导出选项灵活配置&quot;">​</a></h3><p>导出选项中以下功能均可独立开关，配置可保存持久化：</p><p>— <strong>Front Matter 元数据</strong>：总开关 + 9 个字段独立子开关，精细控制导出内容；<br> — <strong>图片处理</strong>：两种模式可选 —— 保留原始 URL（在线查看，不增加体积）或下载到本地并以相对路径引用（可离线查看，适合完整归档迁移）；<br> — <strong>包含文章摘要</strong>：在 Front Matter 中添加 excerpt 字段；<br> — <strong>保留短代码</strong>：原样保留 WordPress 短代码，便于后续手动替换；<br> — <strong>包含原文链接</strong>：在导出文件末尾追加原文永久链接，格式为 <code>**文章原文链接：** &lt;url&gt;</code>，方便追溯来源。</p><h3 id="中英文双语界面" tabindex="-1">中英文双语界面 <a class="header-anchor" href="#中英文双语界面" aria-label="Permalink to &quot;中英文双语界面&quot;">​</a></h3><p>插件内置完整的中英文双语系统，支持三种语言模式：</p><p>— <strong>自动</strong>：根据 WordPress 站点语言自动选择中文或英文界面；<br> — <strong>中文</strong>：强制使用中文界面，Front Matter 字段名同步显示中文键名；<br> — <strong>英文</strong>：强制使用英文界面，Front Matter 字段名显示英文键名。</p><p>语言切换通过管理页面顶部的下拉选择器即时生效，无需保存或刷新。</p><h3 id="导出配置持久化" tabindex="-1">导出配置持久化 <a class="header-anchor" href="#导出配置持久化" aria-label="Permalink to &quot;导出配置持久化&quot;">​</a></h3><p>所有导出选项（Front Matter 字段开关、图片处理模式、摘要开关、短代码开关、原文链接开关）均可通过「保存配置」按钮持久化到 WordPress 的 options 表中。下次进入管理页面时自动恢复上次的配置状态，无需重复设置。</p><h2 id="使用说明" tabindex="-1">使用说明 <a class="header-anchor" href="#使用说明" aria-label="Permalink to &quot;使用说明&quot;">​</a></h2><h3 id="第一步-安装插件" tabindex="-1">第一步：安装插件 <a class="header-anchor" href="#第一步-安装插件" aria-label="Permalink to &quot;第一步：安装插件&quot;">​</a></h3><p>将 <code>wp-markdown</code> 文件夹上传至网站 <code>wp-content/plugins/</code> 目录，进入 WordPress 后台「插件」页面，找到「WP Markdown Export」并点击启用。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/image-32.png" alt=""></p><h3 id="第二步-单篇导出-快捷方式" tabindex="-1">第二步：单篇导出（快捷方式） <a class="header-anchor" href="#第二步-单篇导出-快捷方式" aria-label="Permalink to &quot;第二步：单篇导出（快捷方式）&quot;">​</a></h3><p>在后台「文章 → 所有文章」或「页面 → 所有页面」列表中，将鼠标悬停在任意文章标题上，点击行操作菜单中的「导出 Markdown」链接，浏览器将自动下载该文章的 <code>.md</code> 文件。</p><h3 id="第三步-批量导出" tabindex="-1">第三步：批量导出 <a class="header-anchor" href="#第三步-批量导出" aria-label="Permalink to &quot;第三步：批量导出&quot;">​</a></h3><p>进入后台「工具 → Markdown 导出」页面：</p><p>— 使用筛选条件（分类、状态、日期范围）缩小文章范围，点击「筛选」按钮；<br> — 勾选需要导出的文章，或点击表头复选框全选当前页；<br> — 在「导出选项」模块中按需开启或关闭各项功能；<br> — 点击「导出选中文章」按钮，浏览器将下载包含所有选中文章 Markdown 文件的 ZIP 压缩包。</p><p>如需保存当前配置以便下次复用，点击「保存配置」按钮即可。</p><h3 id="第四步-验证导出结果" tabindex="-1">第四步：验证导出结果 <a class="header-anchor" href="#第四步-验证导出结果" aria-label="Permalink to &quot;第四步：验证导出结果&quot;">​</a></h3><p>— 解压 ZIP 包，检查各 <code>.md</code> 文件的 Front Matter 头部是否包含预期字段；<br> — 用任意 Markdown 编辑器（如 VS Code、Typora）打开文件，确认格式渲染正确；<br> — 如需导入静态站点生成器，将 <code>.md</code> 文件放入对应内容目录即可。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>— 本插件导出的是 Markdown 文本文件，并非 WordPress 的 WXR 格式导入/导出文件。如需完整的 WordPress 数据迁移（含用户、设置等），请使用 WordPress 自带的「导出」工具；<br> — 如果文章内容中包含大量依赖 WordPress 短代码渲染的功能（如表单、画廊），建议开启「保留短代码」选项，待迁移后手动替换；<br> — 图片处理选择「下载到本地」模式时，导出过程会下载远程图片，处理时间与图片数量成正比，大量图片时建议分批导出；<br> — 文章标题包含文件名非法字符（如 <code>/ \\ : * ? &quot; &lt; &gt; |</code>）时，插件会自动将其替换为连字符 <code>-</code>；<br> — 文章标题超过 80 个字符时，文件名会自动截断，请留意同名文章可能导致的文件名冲突。</p><h2 id="反馈与支持" tabindex="-1">反馈与支持 <a class="header-anchor" href="#反馈与支持" aria-label="Permalink to &quot;反馈与支持&quot;">​</a></h2><p>— 作者：softbangong<br> — 作者网站：softbangong.top<br> — 作者网站：softbangong.com<br> — 邮箱：<a href="mailto:yunjuliangpin@163.com" target="_blank" rel="noreferrer">yunjuliangpin@163.com</a><br> — 邮箱：<a href="mailto:softbangong@gmail.com" target="_blank" rel="noreferrer">softbangong@gmail.com</a></p><h2 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to &quot;更新日志&quot;">​</a></h2><h3 id="v1-0-0-2026-07-12" tabindex="-1">v1.0.0（2026-07-12） <a class="header-anchor" href="#v1-0-0-2026-07-12" aria-label="Permalink to &quot;v1.0.0（2026-07-12）&quot;">​</a></h3><p>— 初始版本发布；<br> — 自实现零依赖 HTML 转 Markdown 转换引擎；<br> — 支持 YAML Front Matter 元数据头，9 个字段独立开关；<br> — 支持 WordPress 特有内容预处理（figure/caption/Gutenberg代码块/oEmbed/短代码）；<br> — 单篇导出：文章/页面行操作菜单中一键导出；<br> — 批量导出：多选文章打包为 ZIP 下载，按日期组织文件夹；<br> — 管理界面：文章筛选（分类/状态/日期范围）、分页、全选；<br> — 导出选项持久化保存；<br> — 图片处理双模式（保留原始 URL / 下载本地引用）；<br> — 中英文双语界面，Front Matter 字段名跟随语言切换。</p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/3055.html" target="_blank" rel="noreferrer">https://www.softbangong.com/3055.html</a></p>',54)])])}const b=e(n,[["render",l]]);export{g as __pageData,b as default};
